use anyhow::{ensure,Result};
use std::{env,fs,path::PathBuf};
fn main()->Result<()>{let args:Vec<String>=env::args().collect();ensure!(args.len()==5,"usage: compile_market <source> <fresh-output> <asset-a> <asset-b>");let out=psy_template_u124_markets::compile_market(&fs::read_to_string(&args[1])?,args[3].parse()?,args[4].parse()?)?;let dir=PathBuf::from(&args[2]);fs::create_dir(&dir)?;fs::write(dir.join("compilation_artifact.json"),out.to_compilation_artifact_json()?)?;fs::write(dir.join("abi.json"),out.abi_to_json()?)?;fs::write(dir.join("circuit_defs.json"),serde_json::to_vec(&out.circuit_definitions)?)?;fs::write(dir.join("contract_code.bin"),out.to_bytes()?)?;println!("Resolved foreign ABIs: {} methods; market/U124 height 31, PSY height 32",out.method_count());Ok(())}
